import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { balanceDue } from './payments.js';
import { isValidDate as validateDate } from './dates.js';

/**
 * Generate a customer statement listing outstanding invoices.
 * @param {string} customerId
 * @param {Array<{ customerId: string, number?: string, issueDate: string, dueDate: string, status: string, lines: Array }>} invoices
 * @param {string} asOf - YYYY-MM-DD cutoff date (inclusive)
 * @returns {{ ok: true, value: { customerId: string, invoices: Array<{ number: string, issueDate: string, dueDate: string, total: number, due: number }>, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  // Validate asOf date
  if (!validateDate(asOf)) {
    return fail('DATE_INVALID');
  }

  // Filter invoices for this customer, with issued/partially_paid status, and date on or before asOf
  const statementInvoices = invoices
    .filter((inv) => inv.customerId === normalizedCustomerId)
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.issueDate <= asOf)
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate))
    .map((inv) => {
      const due = balanceDue(inv);
      return {
        number: inv.number || '',
        issueDate: inv.issueDate,
        dueDate: inv.dueDate,
        total: invoiceTotals(inv).value.total,
        due,
      };
    });

  // Calculate total due
  const totalDue = statementInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId: normalizedCustomerId,
    invoices: statementInvoices,
    totalDue,
  });
}

// Helper function to get invoice totals (imported from invoices.js)
function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return { ok: false, error: 'INVOICE_INVALID' };
  }

  let subtotal = 0;
  let totalDiscount = 0;
  let totalVAT = 0;

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    subtotal += lineTotal;

    const lineDiscount = line.discountPercent ? lineTotal * line.discountPercent / 100 : 0;
    totalDiscount += lineDiscount;

    const taxableAmount = lineTotal - lineDiscount;
    const lineVAT = taxableAmount * line.vatRate / 100;
    totalVAT += lineVAT;
  }

  const voucherAmount = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - totalDiscount + totalVAT - voucherAmount);

  return {
    ok: true,
    value: {
      subtotal,
      discount: totalDiscount,
      vat: totalVAT,
      voucher: voucherAmount,
      total: Math.round(total),
    },
  };
}

